head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > M > setColor]<br/>Accordion 컴포넌트의 테두리 색상과 패널 타이틀의 배경색을 설정합니다.",
    "validation" : [
        "options(필수) 색상 변경 설정을 객체로 설정합니다.",
        "options.borderColor(선택) 컴포넌트의 테두리에 적용될 색상을 설정합니다.",
        "options.borderColor 는 색상이름('blue','red'), 색상코드('#rrggbb'), 함수형 색상('rgb(255,0,255)','rgba(255,0,255,0.5)') 등 다양한 형식으로 설정할 수 있습니다.",
        "options.borderColor 값을 설정하지 않으면 테두리 색상을 변경하지 않습니다.",
        "options.panelColor(선택) 모든 패널 타이틀의 배경색에 적용될 색상을 설정합니다.",
        "options.panelColor 는 색상이름('blue','red'), 색상코드('#rrggbb'), 함수형 색상('rgb(255,0,255)','rgba(255,0,255,0.5)') 등 다양한 형식으로 설정할 수 있습니다.",
        "options.panelColor 값을 설정하지 않으면 패널 타이틀의 배경색을 변경하지 않습니다.",
        "비활성화(disabled)된 패널의 색상도 변경됩니다.",
        "setColor() 메소드는 인라인 스타일을 설정하므로, addClass() 메소드로 적용한 CSS 클래스 기반 스타일보다 우선 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // setColor 는 con_ 옵션 없음 (par_borderColor, par_panelColor 만 사용)
    let properties = {
    };

    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* 테스트 순서 : 1) addClass(oddClass) 클릭 → 빨간 1px 테두리 적용 2) setColor({borderColor:파랑}) 호출 → 인라인 색상이 .oddClass 색상보다 우선되어 파란 테두리로 변경 (border-style/width 는 .oddClass 가 제공)"', '', 'label3');
    $c.gcm.createLabel('label="* panels3 : disabledPanels=true (비활성화) → 비활성화 패널의 색상도 변경되는지 검증"', '', 'label4');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="testAddClass">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1 (testAddClass)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" disabledPanels="true">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3 (disabled)"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// setColor 호출 — par_borderColor, par_panelColor 의 값으로 options 객체 구성하여 호출 (빈값이면 해당 속성 제외)
scwin.btn_setColor_onclick = function (e) {
    let borderColor = par_borderColor.getValue();
    let panelColor = par_panelColor.getValue();

    let options = {};
    if (borderColor !== "") {
        options.borderColor = borderColor;
    }
    if (panelColor !== "") {
        options.panelColor = panelColor;
    }

    wf_body_bottom.getObj("scwin").setReturnValue("===== setColor 호출 =====");    
    target1.setColor(options);

    // 실제 적용된 인라인 스타일 확인 (엔진: _accordion.style.borderColor / panels[i]_title.style.background)
    wf_body_bottom.getObj("scwin").setReturnValue("[target1 borderColor] " + target1.render.style.borderColor);
    for (let i = 0; i < target1.panelArr.length; i++) {
        let panelId = target1.panelArr[i].id;
        let titleEl = document.getElementById(panelId + "_title");
        wf_body_bottom.getObj("scwin").setReturnValue("[" + panelId + "_title background] " + (titleEl ? titleEl.style.background : "(DOM 없음)"));
    }
};



// addClass 적용 — oddClass 하드코딩
scwin.btn_addClassCheck_onclick = function (e) {
    target1.addClass("oddClass");
    wf_body_bottom.getObj("scwin").setReturnValue("===== target1.addClass('oddClass') 호출 =====");
};
